<?php require_once __DIR__.'/../includes/admin-auth.php';require_admin(['super_admin']);$pageTitle='Admin accounts';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='create'){$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';$role=$_POST['role']??'checkin_staff';$ve=[];if($m=v_name($name))$ve[]=$m;if($m=v_email($email))$ve[]=$m;if($m=v_password($pass,12))$ve[]=$m;if(!in_array($role,['event_admin','checkin_staff'],true))$ve[]='Select a permitted role.';if($ve)$err=$ve;else{try{$s=$pdo->prepare('INSERT INTO admin_users(name,email,password_hash,role) VALUES(?,?,?,?)');$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT),$role]);log_action($pdo,'admin.create','Created admin '.$email.' role '.$role);flash('success','Admin account created. Share credentials securely.');redirect('admin-users.php');}catch(PDOException $e){$err='Could not create account. Email may already be in use.';}}}elseif($action==='toggle'){$id=(int)($_POST['id']??0);if($id===(int)$_SESSION['admin_id'])$err='You cannot disable your own account.';else{$pdo->prepare("UPDATE admin_users SET is_active=1-is_active WHERE id=? AND role<>?")->execute([$id,'super_admin']);log_action($pdo,'admin.toggle','Toggled admin ID '.$id);flash('success','Admin account status updated.');redirect('admin-users.php');}}}$admins=$pdo->query('SELECT id,name,email,role,is_active,created_at,last_login_at FROM admin_users ORDER BY created_at DESC')->fetchAll();require __DIR__.'/../includes/admin-layout.php'; ?><div class="row g-4"><div class="col-xl-4"><div class="panel"><h2 class="h5">Create admin account</h2><p class="muted small">Only Super Admin can manage accounts. Use a unique password and share it securely.</p><?=render_errors($err)?><form method="post" data-validate novalidate><?=csrf_field()?><input type="hidden" name="action" value="create"><div class="mb-3"><label class="form-label" for="name">Full name</label><input class="form-control" id="name" name="name" required minlength="2" maxlength="60" data-rule="name" value="<?=e(($_POST['action']??'')==='create'?($_POST['name']??''):'')?>"></div><div class="mb-3"><label class="form-label" for="email">Email</label><input class="form-control" id="email" type="email" name="email" required maxlength="120" value="<?=e(($_POST['action']??'')==='create'?($_POST['email']??''):'')?>"></div><div class="mb-3"><label class="form-label" for="password">Temporary password</label><input class="form-control" id="password" type="password" name="password" minlength="12" maxlength="72" data-rule="strongpass" data-strength autocomplete="new-password" required><div class="form-text">At least 12 characters with uppercase, lowercase, a number and a special character.</div></div><div class="mb-4"><label class="form-label" for="role">Role</label><select class="form-select" id="role" name="role" required><option value="checkin_staff">Check-in staff</option><option value="event_admin">Event admin</option></select></div><button class="btn btn-primary w-100">Create account</button></form></div></div><div class="col-xl-8"><div class="panel"><h2 class="h5 mb-3">Administrator directory</h2><div class="table-responsive"><table class="table"><thead><tr><th>Administrator</th><th>Role</th><th>Last login</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($admins as $a): ?><tr><td><strong><?=e($a['name'])?></strong><div class="small muted"><?=e($a['email'])?></div></td><td><?=e(str_replace('_',' ',$a['role']))?></td><td><?=e($a['last_login_at']?date('M j, Y g:i A',strtotime($a['last_login_at'])):'Never')?></td><td><span class="status-pill <?=$a['is_active']?'status-published':'status-cancelled'?>"><?=$a['is_active']?'Active':'Disabled'?></span></td><td><?php if($a['role']!=='super_admin' && (int)$a['id']!==(int)$_SESSION['admin_id']): ?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$a['id']?>"><button class="btn btn-sm btn-outline-secondary"><?=$a['is_active']?'Disable':'Enable'?></button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div></div></div><?php require __DIR__.'/../includes/admin-footer.php'; ?>
